sp_widget.client_script:
api.controller = function($window, $scope, $rootScope, $timeout, $location, spAriaFocusManager, $element) {
    /* global $ */
    //Access options (from option schema) with c.options.<option>

    //////////////////////////////////////////////////////////
    // INIT
    //////////////////////////////////////////////////////////
    /* widget controller */
    var c = this;


    //////////////////////////////////////////////////////////
    // DEFINE FUNCTIONS
    //////////////////////////////////////////////////////////
    //works for "form" widget (and those extending it)
    function getContainerID(element) {
        const str = element.attr("aria-labelledby");

        if (str) {
            return str.split("_")[1];
        } else {
            return '';
        }
    }

    function makeCollapsible(selector) {
        const randNum = Math.floor(Math.random() * 1000); //allows widget more than once per page

        $(selector).each(function(index) {
            //console.log('------in: ' + index + '------');

            const containerId = getContainerID($(this));

            if (containerId) { //container is identified
                const sectionTitle = $(this).find(c.options.button_selector);
                const sectionData = $(this).find(c.options.content_selector);
                const sectionId = "hocCollapsibleSection" + randNum + "i" + index; //must not contain spaces or "."

							  sectionTitle.addClass("sectioncollapseexpand");
                //console.log(sectionTitle.text() + ' - ' + containerId);

                //if section behavior captured
                if (c.data.sections && containerId in c.data.sections) { //could also use c.data.sections.hasOwnProperty(containterId)

                    if (c.data.sections[containerId].collapsible == true) {
                        sectionTitle.attr("data-toggle", "collapse");
                        sectionTitle.attr("data-target", "#" + sectionId);

                        //set section
                        sectionData.attr("id", sectionId);
                        if (c.data.sections[containerId].startOpen == true) {
                            sectionData.addClass("collapse in"); //"collapse in" = expanded, "collapse" = collapsed
                        } else {
                            sectionData.addClass("collapse"); //"collapse in" = expanded, "collapse" = collapsed
                        }
                    }
                } else if (c.data.sections && 'defaultSection' in c.data.sections) { //else use the default section behavior (if it exist)
                    if (c.data.sections['defaultSection'].collapsible == true) {
                        sectionTitle.attr("data-toggle", "collapse");
                        sectionTitle.attr("data-target", "#" + sectionId);

                        //set section
                        sectionData.attr("id", sectionId);
                        if (c.data.sections['defaultSection'].startOpen == true) {
                            sectionData.addClass("collapse in"); //"collapse in" = expanded, "collapse" = collapsed
                        } else {
                            sectionData.addClass("collapse"); //"collapse in" = expanded, "collapse" = collapsed
                        }
                    } //else id found but not matched and defaultSection undefined 
                } else { //else, default to collapsible and open (if behavior is empty, will default to this)
                    sectionTitle.attr("data-toggle", "collapse");
                    sectionTitle.attr("data-target", "#" + sectionId);

                    //set section
                    sectionData.attr("id", sectionId);
                    sectionData.addClass("collapse in"); //"collapse in" = expanded, "collapse" = collapsed
                }
            } //else{}//container isn't identified (probably doesn't have a title to click on)


            //console.log('------out: ' + index + '------');
        });
    }

    //////////////////////////////////////////////////////////
    //MAIN LOGIC
    //////////////////////////////////////////////////////////

    $timeout(function() { //Wait for page to fully render (would be better to listen to an event but for now this works)
        makeCollapsible(c.options.section_selector);
    }, 500);
}

sp_widget.css:
.dropdown_title {
  display: inline-block;
  border: 2px solid red;
}
.hira_back_link {
  margin: 5px 0 0 0;
  padding: 0;
}

.btn-default {
  display: none;
}

.noshow {
  display: none;
}

#\.annotation\.cd5c7666fb42165495e5fb3f4eefdc77, #\.annotation\.c15c7666fb42165495e5fb3f4eefdc78, #\.annotation\.855c7666fb42165495e5fb3f4eefdc78 {
   font-weight: bold;
  font-size: x-large;
}

#\.annotation\.495c7666fb42165495e5fb3f4eefdc78 {
  color: red;
  font-weight: bold;
}


.sectioncollapseexpand .container-caption.form-container-caption.ng-scope {
  margin-bottom: 1.5rem;
}

.sectioncollapseexpand .h4.ng-binding {
  width: 100%;
  display: block;
  background-color: rgb(198, 198, 198);
  color: rgb(51, 51, 51);
  border: 1px solid rgb(66, 122, 38);
  padding: 14px 10px 10px;
  position: relative;
  cursor: pointer;
  transition: background-color, color 0.25s;
  margin-top: 0.1rem;
  margin-bottom: 0rem;
}

/* Down-pointing arrow */
.sectioncollapseexpand .h4.ng-binding:after {
  content: "▼";
  position: absolute;
  right: 10px;
  font-size: 14px;
  transition: transform 0.2s ease;
}

sp_widget.script:
(function(input) {
    /* global data, options, $sp */
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
    //Access options (from option schema) with options.<option><

    //////////////////////////////////////////////////////////
    // DEFINE FUNCTIONS
    //////////////////////////////////////////////////////////
    function defineSectionStates(sections) {
        gs.debug('OHSM COLLAPSIBLE WIDGET --- input sections: ' + JSON.stringify(sections));
        for (const section of sections) {
            const obj = {
                collapsible: section.collapsible,
                startOpen: section.startOpen
            };

            data.sections[section.sys_ui_section_id] = obj;
        }
        gs.debug('OHSM COLLAPSIBLE WIDGET --- sections: ' + JSON.stringify(data.sections));
    }

    //////////////////////////////////////////////////////////
    //MAIN LOGIC
    //////////////////////////////////////////////////////////

    const id = $sp.getParameter("id"); //Check if widget is in designer or not (ID isn't a param in designer but is in portal)

    if (gs.nil(id)) {
        data.id_empty = true;
        data.id_label = id;
    } else {

        const table = $sp.getParameter("table");
        const sys_id = $sp.getParameter("sys_id");
        const gr = new GlideRecordSecure(table);

        gr.get(sys_id);

        if (gr.isValid()) {
            gs.debug('OHSM COLLAPSIBLE WIDGET --- gr valid');
            if (gs.nil(options.behavior_object)) {
                gs.debug('OHSM COLLAPSIBLE WIDGET --- behavior nil');
                return; //if behavior empty defaults to all collapsible & all open by default
            }
            const behaviors = JSON.parse(options.behavior_object);
            let sectionDefaults;

            data.sections = {};

            /* // behavior object
            [{
            	"glideFilterString": "<glideFilterString>",
            	"sections": [{"sys_ui_section_id": "<id>|'defaultSection'", "collapsible": true|false, "startOpen": true|false}],
            }]*/

            for (const behavior of behaviors) {
                //if glideFilterString empty then it's the default state
                if (gs.nil(behavior.glideFilterString)) {
                    sectionDefaults = behavior.sections;
                }

                if (GlideFilter.checkRecord(gr, behavior.glideFilterString)) {
                    defineSectionStates(behavior.sections);
                }
            }

            //No filter match, then use default state
            if (!gs.nil(sectionDefaults) && (gs.nil(data.sections) || data.sections.length === 0)) {
                defineSectionStates(sectionDefaults);
            }
        }
    }
})();
